"""Text of the EU methods page (critical-methods.html), English and Finnish (draft). Merged into COPY by critical_copy.py; see there for the rules."""

METHODS = {
    'm.critical.h': ('What “critical” means here', 'Mitä ”kriittinen” tarkoittaa tässä'),
    'm.sources.h': ('Sources', 'Lähteet'),
    'm.src.eu': ('<strong>EU list.</strong> <a href="{ema_list}">Union list of critical medicines</a>, European Medicines Agency (EMA) and the Heads of Medicines Agencies. We use version {version} ({reference}, {published}) and keep it fixed. It has {rows} rows, one for each ATC level 5 code. The route text of a row can name several routes. The file has no dosage form column. We keep the sheet row of each entry.',
                 '<strong>EU:n luettelo.</strong> <a href="{ema_list}">Union list of critical medicines</a>, Euroopan lääkevirasto EMA ja Heads of Medicines Agencies. Käytämme versiota {version} ({reference}, {published}) ja pidämme sen muuttumattomana. Siinä on {rows} riviä, yksi kutakin ATC-tason 5 koodia kohti. Rivin antoreittiteksti voi nimetä useita antoreittejä. Tiedostossa ei ole lääkemuotosaraketta. Säilytämme jokaisen kohdan taulukkorivin.'),
    'm.src.shortage': ('<strong>Fimea shortage file.</strong> <code>Shortages.txt</code> (also published as <code>Saatavuushairiot.txt</code>, with Finnish column names) from <a href="{licence}">Fimea open data</a>. It lists packages by VNR with the company’s start and estimated end dates. Fimea does not keep a history of this file and the dates are estimates. Only products that have a VNR appear.',
                       '<strong>Fimean saatavuushäiriötiedosto.</strong> <code>Shortages.txt</code> (julkaistaan myös nimellä <code>Saatavuushairiot.txt</code>, suomenkielisillä sarakenimillä) <a href="{licence}">Fimean avoimesta datasta</a>. Se listaa pakkaukset VNR-numeron mukaan yrityksen ilmoittamine alkamis- ja arvioitu päättymispäivineen. Fimea ei säilytä tämän tiedoston historiaa, ja päivämäärät ovat arvioita. Mukana ovat vain valmisteet, joilla on VNR.'),
    'm.src.register': ('<strong>Fimea basic register.</strong> <code>{register}</code>, with the ATC code, the dosage form, the route of administration (<code>Antoreitti</code>), the active substances and Fimea’s own flag <code>EUKriittinenValmiste</code>. We read the 225 MB file as a stream.',
                       '<strong>Fimean perusrekisteri.</strong> <code>{register}</code>, jossa ovat ATC-koodi, lääkemuoto, antoreitti (<code>Antoreitti</code>), vaikuttavat aineet ja Fimean oma merkintä <code>EUKriittinenValmiste</code>. Luemme 225 Mt:n tiedoston virtana.'),
    'm.src.forms': ('<strong>Dosage form names.</strong> <code>pharmaceutical_form.csv</code> from Fimea. It has form names and translations only. We use it for the English form names we show. It does not decide a match.',
                    '<strong>Lääkemuotojen nimet.</strong> <code>pharmaceutical_form.csv</code> Fimealta. Siinä on vain lääkemuotojen nimet ja käännökset. Käytämme sitä näytettävien englanninkielisten lääkemuotojen nimien lähteenä. Se ei ratkaise täsmäystä.'),
    'm.src.archive': ('<strong>Archive.</strong> Our own captures of the shortage file, daily since 21 Nov 2026, and earlier captures from the Internet Archive.',
                      '<strong>Arkisto.</strong> Omat tilannekuvamme saatavuushäiriötiedostosta, päivittäin 21.11.2026 alkaen, sekä aiemmat tilannekuvat Internet Archivesta.'),
    'm.licences.h': ('Licences and credit', 'Lisenssit ja lähdetiedot'),
    'm.lic.fimea': ('<strong>Fimea.</strong> Fimea’s open data is licensed under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. The licence asks for the name of the licensor, the name of the material and the date and time it was released by Fimea. Fimea does not give release times; we show the file’s last-modified time instead. We select, join and transform the data. Fimea does not endorse this site.',
                    '<strong>Fimea.</strong> Fimean avoin data on lisensoitu <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a> -lisenssillä. Lisenssi edellyttää lisenssinantajan nimeä, aineiston nimeä sekä Fimean julkaisupäivää ja -aikaa. Fimea ei ilmoita julkaisuaikoja; näytämme sen sijaan tiedoston viimeisimmän muokkausajan. Valitsemme, yhdistämme ja muokkaamme aineistoa. Fimea ei tue tätä sivustoa.'),
    'm.lic.ema': ('<strong>EMA.</strong> EMA’s <a href="{notice}">copyright notice</a> says its web content may be reproduced and distributed, for non-commercial and commercial purposes, if EMA is always acknowledged as the source. It is not a Creative Commons licence. We show EMA as the source of the list wherever the list is used, including in the downloads.',
                  '<strong>EMA.</strong> EMAn <a href="{notice}">tekijänoikeusilmoituksen</a> mukaan sen verkkosisältöä saa jäljentää ja levittää sekä ei-kaupallisiin että kaupallisiin tarkoituksiin, jos EMA mainitaan aina lähteenä. Se ei ole Creative Commons -lisenssi. Mainitsemme EMAn listan lähteenä aina, kun listaa käytetään, myös ladattavissa tiedostoissa.'),
    'm.lic.credit': ('Source credit used in the downloads and feeds: {credit}', 'Ladattavissa tiedostoissa ja syötteissä käytetty lähdetieto (englanniksi): {credit}'),
    'm.lic.code': ('Code on this site: MIT licence.', 'Tämän sivuston koodi: MIT-lisenssi.'),
    'm.types.h': ('What the match types mean', 'Mitä täsmäystyypit tarkoittavat'),
    'm.rule.h': ('The match rule', 'Täsmäyssääntö'),
    'm.rule.atc': ('<strong>ATC code.</strong> The ATC level 5 code of the product in the Fimea register must be exactly a code on the EU list. Fimea gives one ATC code for each product.',
                   '<strong>ATC-koodi.</strong> Valmisteen ATC-tason 5 koodin Fimean rekisterissä on oltava täsmälleen sama kuin jokin EU:n luettelon koodi. Fimea antaa jokaiselle valmisteelle yhden ATC-koodin.'),
    'm.rule.ingredient': ('<strong>Active ingredient.</strong> The substance of the list row must be among the product’s active ingredients (all of them, for a list row that names several, such as piperacillin and tazobactam). A name counts when it is the same, or when the register name starts with it (“Ipratropium bromide” for IPRATROPIUM). A few list names are spelled differently in the register (adrenaline and epinephrine, vaccines, blood products); they are in <a href="https://github.com/AlejandroRenalias/shortage-radar/blob/main/data/critical/ingredients.json"><code>data/critical/ingredients.json</code></a>. Extra ingredients are allowed, so a combination product with the list substance passes. If the substance is not there, or Fimea gives no ingredients, the package is shown as <em>Ingredient not confirmed</em> and is neither an exact match nor an alert. Example: B. Braun sodium chloride (VNR 389066) has the ATC code of potassium chloride and a fitting route, but its ingredient is sodium chloride.',
                          '<strong>Vaikuttava aine.</strong> Luettelon rivin aineen on oltava valmisteen vaikuttavien aineiden joukossa (kaikkien, jos luettelon rivi nimeää useita, kuten piperasilliini ja tatsobaktaami). Nimi kelpaa, kun se on sama tai kun rekisterin nimi alkaa sillä (”Ipratropium bromide” nimelle IPRATROPIUM). Muutama luettelon nimi kirjoitetaan rekisterissä eri tavalla (adrenaliini ja epinefriini, rokotteet, verivalmisteet); ne ovat tiedostossa <a href="https://github.com/AlejandroRenalias/shortage-radar/blob/main/data/critical/ingredients.json"><code>data/critical/ingredients.json</code></a>. Lisäaineet sallitaan, joten yhdistelmävalmiste, jossa on luettelon aine, kelpaa. Jos ainetta ei ole tai Fimea ei anna vaikuttavia aineita, pakkaus näytetään merkinnällä <em>Vaikuttavaa ainetta ei vahvistettu</em>, eikä se ole täsmällinen osuma eikä hälytys. Esimerkki: B. Braunin natriumkloridilla (VNR 389066) on kaliumkloridin ATC-koodi ja sopiva antoreitti, mutta sen vaikuttava aine on natriumkloridi.'),
    'm.rule.route': ('<strong>Route.</strong> A route of the product (Fimea <code>Antoreitti</code>) must fit a route of the list row. A table in <a href="https://github.com/AlejandroRenalias/shortage-radar/blob/main/data/critical/routes.json"><code>data/critical/routes.json</code></a> says which Fimea route fits which EU route term. There are no keyword rules. Three broader EU terms are handled in the table: “parenteral use” fits every route that the table marks as parenteral (injection, infusion or implantation into the body: a vein, artery, muscle, under the skin, a joint, a body cavity, implantation and the like), “intravascular use” fits a vein, an artery or a coronary artery, and “intraocular use” fits routes into the eye (front chamber, vitreous, retina, inside the eye). A route is marked parenteral only when the route itself says so: “into a lesion” (code 1033) is not assumed to be an injection.',
                     '<strong>Antoreitti.</strong> Valmisteen antoreitin (Fimean <code>Antoreitti</code>) on sovittava luettelon rivin antoreittiin. Taulukko tiedostossa <a href="https://github.com/AlejandroRenalias/shortage-radar/blob/main/data/critical/routes.json"><code>data/critical/routes.json</code></a> kertoo, mikä Fimean antoreitti sopii mihinkin EU:n antoreittitermiin. Avainsanasääntöjä ei ole. Kolme laajempaa EU-termiä käsitellään taulukossa: ”parenteral use” sopii jokaiseen antoreittiin, jonka taulukko merkitsee parenteraaliseksi (injektio, infuusio tai implantointi kehoon: laskimo, valtimo, lihas, ihon alle, nivel, kehon onkalo, implantointi ja vastaavat), ”intravascular use” sopii laskimoon, valtimoon tai sepelvaltimoon ja ”intraocular use” sopii silmän sisään vieviin antoreitteihin (etukammio, lasiainen, verkkokalvo, silmän sisään). Antoreitti merkitään parenteraaliseksi vain, kun antoreitti itse sen sanoo: ”kudosvaurioon, leesioon” (koodi 1033) ei oleteta injektioksi.'),
    'm.rule.result': ('<strong>Result.</strong> ATC code, ingredient and route fit: <em>Exact match</em>. ATC code and ingredient on the list, route does not fit: <em>Route does not fit</em> (<code>route-mismatch</code> in the downloads). ATC code on the list, ingredient not confirmed: <em>Ingredient not confirmed</em> (<code>ingredient-mismatch</code>). VNR not in the register: <em>Not in the register</em> (<code>unmatched</code>).',
                      '<strong>Tulos.</strong> ATC-koodi, vaikuttava aine ja antoreitti sopivat: <em>Täsmällinen osuma</em>. ATC-koodi ja vaikuttava aine ovat luettelossa, antoreitti ei sovi: <em>Antoreitti ei sovi</em> (<code>route-mismatch</code> ladattavissa tiedostoissa). ATC-koodi on luettelossa, vaikuttavaa ainetta ei vahvistettu: <em>Vaikuttavaa ainetta ei vahvistettu</em> (<code>ingredient-mismatch</code>). VNR ei ole rekisterissä: <em>Ei rekisterissä</em> (<code>unmatched</code>).'),
    'm.rule.ongoing': ('<strong>Ongoing or starts later.</strong> Fimea marks each notice as ongoing (Voimassa K, “Kyllä”) or not yet started (E, “Ei”). The counts show ongoing shortages only; notices that start later are listed apart, marked “Starts later”, with their start date. The counts carry the date of the shortage file.',
                       '<strong>Käynnissä tai alkaa myöhemmin.</strong> Fimea merkitsee jokaisen ilmoituksen käynnissä olevaksi (Voimassa K, ”Kyllä”) tai ei vielä alkaneeksi (E, ”Ei”). Luvut näyttävät vain käynnissä olevat saatavuushäiriöt; myöhemmin alkavat ilmoitukset listataan erikseen merkinnällä ”Alkaa myöhemmin” ja alkamispäivineen. Luvuissa on saatavuushäiriötiedoston päiväys.'),
    'm.rule.unclear': ('<strong>Route unclear.</strong> If Fimea gives no route, or only “route not relevant”, or a route that is not in our table, the package is not matched on route. It is shown as <em>Route does not fit</em> and the note says “Route unclear”. We do not guess.',
                       '<strong>Antoreitti epäselvä.</strong> Jos Fimea ei anna antoreittiä tai antaa vain ”Antoreitti ei oleellinen” tai antoreitin, jota ei ole taulukossamme, pakkausta ei täsmätä antoreitin perusteella. Se näytetään merkinnällä <em>Antoreitti ei sovi</em>, ja huomautuksessa lukee ”Antoreitti epäselvä”. Emme arvaa.'),
    'm.rule.cross': ('<strong>Cross-check.</strong> Fimea’s flag <code>EUKriittinenValmiste</code> is not used to decide. Where it disagrees with the match, the note and the CSV say so.',
                     '<strong>Ristiintarkistus.</strong> Fimean merkintää <code>EUKriittinenValmiste</code> ei käytetä päätöksessä. Kun se on eri mieltä täsmäyksen kanssa, huomautus ja CSV kertovat sen.'),
    'm.checked.h': ('Rows checked by hand', 'Käsin tarkistetut rivit'),
    'm.checked.th.package': ('Package', 'Pakkaus'),
    'm.checked.th.result': ('Result', 'Tulos'),
    'm.checked.th.why': ('Why', 'Syy'),
    'm.checked.note': ('Tests in the repository check the route rule on these four cases.', 'Repositorion testit tarkistavat antoreittisäännön näissä neljässä tapauksessa.'),
    'm.check.1': ('Product route is under the tongue (Fimea route code 1070). The list row H01BA02 has intramuscular, intravenous and subcutaneous use.',
                  'Valmisteen antoreitti on kielen alle (Fimean antoreittikoodi 1070). Luettelon rivillä H01BA02 on lihakseen, laskimoon ja ihon alle (intramuscular, intravenous ja subcutaneous use).'),
    'm.check.2': ('Under the tongue (code 1070), as above.', 'Kielen alle (koodi 1070), kuten yllä.'),
    'm.check.3': ('Under the tongue (code 1070), as above.', 'Kielen alle (koodi 1070), kuten yllä.'),
    'm.check.4': ('The register says by mouth (code 1055); the product information says sublingual. The list row H01BA02 has intramuscular, intravenous and subcutaneous use, so neither fits.',
                  'Rekisterin mukaan suun kautta (koodi 1055); valmisteyhteenvedon mukaan sublingvaalisesti. Luettelon rivillä H01BA02 on lihakseen, laskimoon ja ihon alle, joten kumpikaan ei sovi.'),
    'm.check.5': ('By mouth in the register, as above. We use the register, so this stays a route mismatch.', 'Rekisterissä suun kautta, kuten yllä. Käytämme rekisteriä, joten tämä jää antoreitin ristiriidaksi.'),
    'm.check.6': ('ATC code S01EB09 and the route match the list (intraocular use; Fimea route code 1092, into the front chamber of the eye). Fimea’s own flag is 0, so Fimea and the list differ for this package. The note says so.',
                  'ATC-koodi S01EB09 ja antoreitti täsmäävät luetteloon (intraocular use; Fimean antoreittikoodi 1092, silmän etukammion sisään). Fimean oma merkintä on 0, joten Fimea ja luettelo poikkeavat toisistaan tämän pakkauksen kohdalla. Huomautus kertoo tämän.'),
    'm.limits.h': ('Known limits', 'Tunnetut rajoitukset'),
    'm.lim.1': ('Fimea’s shortage file has no history, and its dates are estimates. Our history starts when we first saved the file; it is made of captures, not daily readings.',
                'Fimean saatavuushäiriötiedostossa ei ole historiaa, ja sen päivämäärät ovat arvioita. Historiamme alkaa, kun tallensimme tiedoston ensimmäisen kerran; se koostuu tilannekuvista, ei päivittäisistä lukemista.'),
    'm.lim.2': ('A package that leaves the file is “last seen” on the date of the last capture. That is not proof that supply returned.',
                'Tiedostosta poistuvan pakkauksen ”viimeksi nähty” -päivä on viimeisen tilannekuvan päivä. Se ei todista, että saatavuus on palautunut.'),
    'm.lim.3': ('<strong>Gaps in the captures.</strong> Two consecutive captures more than {max} days apart (exactly {max} days is still joined) tell nothing about the days between them. A notice listed on both sides was not observed in between, and a notice that is new or gone across such a gap started or ended at an unknown time. Every page, feed and download uses this one limit. In the downloads (<code>data.json</code>), each notice lists its runs of captures in <code>spans</code> and the stretches not observed in <code>gaps</code>.',
                '<strong>Aukot tilannekuvissa.</strong> Kaksi peräkkäistä tilannekuvaa, joiden välillä on yli {max} päivää (täsmälleen {max} päivää yhdistetään vielä), ei kerro mitään niiden välisistä päivistä. Ilmoitusta, joka on listalla molemmin puolin, ei havaittu välissä, ja ilmoitus, joka on uusi tai poistunut tällaisen aukon yli, alkoi tai päättyi tuntemattomana ajankohtana. Jokainen sivu, syöte ja lataus käyttää tätä yhtä rajaa. Ladattavissa tiedostoissa (<code>data.json</code>) kunkin ilmoituksen tilannekuvajaksot ovat kentässä <code>spans</code> ja havaitsemattomat jaksot kentässä <code>gaps</code>.'),
    'm.lim.4': ('A notice that Fimea edits (a changed start, end or notification date) shows in the file as a new notice. We count a notice that was edited, or that was missing from some captures and came back, as one shortage. A gap between captures is unknown time, not a new start. A gap is long when two captures are more than {max} days apart. The length we give is “days between captures”: from the first to the last capture that listed the shortage.',
                'Ilmoitus, jota Fimea muokkaa (muuttunut alkamis-, päättymis- tai ilmoituspäivä), näkyy tiedostossa uutena ilmoituksena. Laskemme ilmoituksen, jota on muokattu tai joka puuttui joistakin tilannekuvista ja palasi, yhdeksi saatavuushäiriöksi. Aukko tilannekuvien välillä on tuntematonta aikaa, ei uusi alku. Aukko on pitkä, kun kahden tilannekuvan välillä on yli {max} päivää. Antamamme pituus on ”päiviä tilannekuvien välillä”: ensimmäisestä viimeiseen tilannekuvaan, jossa saatavuushäiriö oli listalla.'),
    'm.lim.5': ('The register describes today. We join old notices to today’s register, so a product that changed ATC code or route since then is shown as it is today.',
                'Rekisteri kuvaa nykytilannetta. Yhdistämme vanhat ilmoitukset nykyiseen rekisteriin, joten valmiste, jonka ATC-koodi tai antoreitti on sittemmin muuttunut, näytetään sellaisena kuin se on nyt.'),
    'm.lim.6': ('The EU list names a substance and routes, not dosage forms or strengths. A match says that the substance and route are on the list, not that this exact product is one the EU list is about.',
                'EU:n luettelo nimeää aineen ja antoreitit, ei lääkemuotoja eikä vahvuuksia. Täsmäys kertoo, että aine ja antoreitti ovat luettelossa, ei sitä, että juuri tämä valmiste on se, jota EU:n luettelo tarkoittaa.'),
    'm.lim.7': ('Combination products are matched by their own ATC code, and the list substance must be among their ingredients. The other ingredients are not checked against the list.',
                'Yhdistelmävalmisteet täsmätään niiden oman ATC-koodin mukaan, ja luettelon aineen on oltava niiden vaikuttavien aineiden joukossa. Muita vaikuttavia aineita ei tarkisteta luetteloa vasten.'),
    'm.lim.8': ('Shortages of products without a VNR are not in Fimea’s file, so they are not here.', 'Valmisteiden, joilla ei ole VNR:ää, saatavuushäiriöt eivät ole Fimean tiedostossa, joten ne eivät ole tässä.'),
    'm.lim.9': ('The EU list changes. We keep version {version} until we check and update it.', 'EU:n luettelo muuttuu. Pidämme version {version}, kunnes tarkistamme ja päivitämme sen.'),
    'm.lim.10': ('The match and the alerts are facts from public files. They give no advice, no risk score and no forecast. They do not name alternatives.',
                 'Täsmäys ja hälytykset ovat julkisten tiedostojen tietoja. Ne eivät anna neuvoja, riskipisteitä eivätkä ennusteita. Ne eivät nimeä vaihtoehtoja.'),
    'm.alerts.h': ('Alerts', 'Hälytykset'),
    'm.alerts': ('The alert feeds list new shortages of packages with an exact match: the first capture that lists the shortage, with its VNR, ATC code, company and dates, and whether Fimea marks it ongoing or not yet started. Each shortage has one entry with a fixed id; an edited notice or one that returns after a missing capture is not a new alert. The daily build writes the feeds. Shortages already on the list when the archive started, already listed for the same VNR in the capture before, or first seen more than {max} days after the capture before (their start is unknown), are not new.',
                 'Hälytyssyötteet listaavat täsmällisen osuman pakkausten uudet saatavuushäiriöt: ensimmäinen tilannekuva, jossa saatavuushäiriö on listalla, sen VNR, ATC-koodi, yritys ja päivämäärät sekä tieto siitä, merkitseekö Fimea sen käynnissä olevaksi vai ei vielä alkaneeksi. Jokaisella saatavuushäiriöllä on yksi merkintä kiinteällä tunnisteella; muokattu ilmoitus tai ilmoitus, joka palaa puuttuneen tilannekuvan jälkeen, ei ole uusi hälytys. Päivittäinen rakennus kirjoittaa syötteet. Saatavuushäiriöt, jotka olivat listalla jo arkiston alkaessa, jotka olivat samalle VNR:lle listalla jo edellisessä tilannekuvassa tai jotka nähtiin ensimmäisen kerran yli {max} päivää edellisen tilannekuvan jälkeen (alkamisajankohta ei tiedossa), eivät ole uusia.'),
}
